Page.validateAndSubmit = function() {
  if (!Page.Widgets.input1.datavalue || !Page.Widgets.input2.datavalue) {
    App.Actions.toastError.invoke({
      message: "Please fill all required fields",
      class: "error",
      position: "top right"
    });
    return;
  }
  Page.Variables.createUserVariable.setInput({
    name: Page.Widgets.input1.datavalue,
    email: Page.Widgets.input2.datavalue
  });
  Page.Variables.createUserVariable.invoke();
};
